css:
.mz *,.mz *::before,.mz *::after{box-sizing: border-box; margin: 0; padding: 0;}
.mz .texto-box{border: 2px solid var(--bosque); border-radius: 12px; padding: 10px 12px; margin-bottom: 10px; width: 100%;}
.mz .texto-parrafo{font-size: 16px; font-weight: 600; line-height: 1.55;}
.mz .preguntas-lista{display: flex; flex-direction: column; gap: 7px; margin-bottom: 10px;}
.mz .pregunta-item{display: flex; flex-direction: column; gap: 2px;}
.mz .pregunta-texto{font-size: 15px; font-weight: 700;}
.mz .respuesta-linea{border-bottom: 1.5px solid var(--bosque); height: 20px; width: 100%;}
.mz .opciones-lista{display: flex; flex-direction: column; gap: 8px; margin-bottom: 10px;}
.mz .opcion-item{display: flex; align-items: flex-start; gap: 10px;}
.mz .opcion-circulo{width: 22px; height: 22px; border: 2px solid var(--bosque); border-radius: 50%; flex-shrink: 0; margin-top: 2px;}
.mz .opcion-letra{font-size: 15px; font-weight: 700; white-space: nowrap; line-height: 1.5;}
.mz .opcion-texto{font-size: 15px; font-weight: 600; line-height: 1.4;}
.mz .clasificar-lista{display: flex; flex-direction: column; gap: 10px; margin-bottom: 10px;}
.mz .clasificar-item{display: flex; align-items: center; gap: 12px;}
.mz .clasificar-cuadro{width: 22px; height: 22px; border: 2px solid var(--bosque); flex-shrink: 0;}
.mz .clasificar-texto{font-size: 15px; font-weight: 600; line-height: 1.3;}
.mz .escribir-lineas{display: flex; flex-direction: column; gap: 6px; margin-bottom: 8px;}
.mz .escribir-linea{border-bottom: 1.5px solid var(--bosque); height: 22px; width: 100%;}
.mz .txt-flex{flex: 1 1 auto; min-width: 0;}
.mz .clasificar-texto,.mz .opcion-texto,.mz .texto-parrafo{line-height: 1.725 !important;}
